import React from "react";
import "./Properties.css"
import JqpUtil from "./JqpUtil";
import {Form, Input, Select} from "antd";
import TextArea from "antd/es/input/TextArea";
const statusOptions = window.statusOptions;
export default class Properties extends React.Component{
    state = {
        lf:this.props.lf,
        curNode:this.props.curNode
    }
    constructor(props) {
        super(props);
    }
    updateNode(node,lf){
        this.setState({
            curNode:node,
            lf:lf
        })
    }
    onChangeSelect(name,value,multiple){
        //console.info(name,value,multiple)


        value = multiple ? value.join(',') : value;
        this.state.curNode.data.properties[name] = value;
        this.setState({
            curNode:this.state.curNode
        });
        let prop = {};

        prop[name] = value;
        if(this.state.curNode.data.type == 'JqpSequenceFlow'){

            this.state.lf.getEdgeModelById(this.state.curNode.data.id).setProperties(prop);
        }else{
            this.state.lf.getNodeModelById(this.state.curNode.data.id).setProperties(prop);
        }
    }
    onChange(e){
        //console.info("onChange",e);
        //console.info(this.state.lf.getGraphRawData());
        let value = this.getValue(e);
        const name = e.target.name;
        this.state.curNode.data.properties[name] = value;
        this.setState({
            curNode:this.state.curNode
        });
        let prop = {};

        prop[name] = value;
        if(this.state.curNode.data.type == 'JqpSequenceFlow'){

            this.state.lf.getEdgeModelById(this.state.curNode.data.id).setProperties(prop);
        }else{
            this.state.lf.getNodeModelById(this.state.curNode.data.id).setProperties(prop);
        }

    }

    getProperty(label,name,type,multiple,options,condition,placeholder){
        if(condition && !condition()){
            return null;
        }
        const readOnly = window.readOnly || false;
        if(options){
            return <Form.Item extra={placeholder} style={{
            display:"inline-block",
            width:"30%"
        }} label={label} key={name}>
                <Select allowClear={true} mode={multiple?"multiple" : ""} style={{
                    width:"100%"
                }} disabled={readOnly}  value={this.state.curNode.data.properties[name] || ''} name={name} onChange={(e)=>{this.onChangeSelect(name,e,multiple)}}  >
                    {
                        options.map(({label,value})=><Select.Option key={value} value={value}>{label}</Select.Option>)
                    }
                </Select>
            </Form.Item>;
        }
        if(type == "textarea"){
            return <Form.Item extra={placeholder} style={{
            display:"inline-block",
            width:"30%"
        }} label={label} key={name}>
                <TextArea  disabled={readOnly} name={name} value={this.state.curNode.data.properties[name] || ''} onChange={(e)=>{this.onChange(e)}} />
            </Form.Item>;
        }
        if(name === "status"){
            return  <Form.Item extra={placeholder} style={{
            display:"inline-block",
            width:"30%"
        }} label={label} key={name}>
                <Select allowClear={true}  mode={multiple?"multiple" : ""} style={{
                    width:"100%"
                }} disabled={readOnly}  value={this.getStatusValue(this.state.curNode.data.properties[name] || '',multiple)} name={name} onChange={(e)=>{this.onChangeSelect(name,e,multiple)}} onClear={(e)=>{this.onChangeSelect(name,multiple?[]:"",multiple)}}  >
                    {
                        statusOptions.map(({label,value})=><Select.Option key={value} value={value}>{label}</Select.Option>)
                    }
                </Select>
            </Form.Item>;
        }
        return  <Form.Item extra={placeholder} style={{
            display:"inline-block",
            width:"30%"
        }} label={label}  key={name}>
                     <Input disabled={readOnly} name={name} value={this.state.curNode.data.properties[name] || ''} onChange={(e)=>{this.onChange(e)}} />
            </Form.Item>;
    }
    getStatusValue(value,multiple){
        if(!multiple){
            return value;
        }
        if(value == '' || value == null){
            return [];
        }
        return value.split(",");
    }
    getValue(e){
        //console.info(e,e);
        if(!e.target.multiple){
            return e.target.value;
        }
        let arr = [];
        for (let i = 0; i < e.target.options.length; i++) {
            let option = e.target.options[i];
            if(option.selected){
                arr.push(option.value);
            }
        }
        return arr.join(",");
    }
    getProperties(arr){
        return <>{arr.map(({label,name,type,multiple,options,condition,placeholder})=>this.getProperty(label,name,type,multiple,options,condition,placeholder||label))}</>
    }

    getEditors(){

        const {curNode,lf} = this.state;
        const nodeData = curNode.data;
        const nodeType = nodeData.type;
        let content = null;

        let context = JqpUtil.buildGraphContext(lf.getGraphData());


        if(nodeType == 'JqpStart' || nodeType == 'JqpEnd'){
            //开始节点/结束节点
        }else if(nodeType == 'JqpSequenceFlow'){
            let edge = context.edgeMap[nodeData.id];
            let sourceNode = context.nodeMap[edge.sourceNodeId];
            if(sourceNode.type == 'JqpStart' || sourceNode.type == 'JqpEnd'){
                return null;
            }

            if(sourceNode.type == 'JqpUserTask'){
                //流转节点
                content = this.getProperties([
                    {label:"当前状态",placeholder:"当此条件流转时,修改当前表的状态,如果为空,则不更新",name:"status"},
                    {label:"前置接口",placeholder:"magicApi地址,post请求,用于此操作之前的校验,返回字符串类型,如果不为空字符串,则提示报错内容",name:"beforeApi"},
                    {label:"后置接口",placeholder:"magicApi地址,post请求,用于此操作之后的更新数据",name:"afterApi"}
                    //{label:"激活",name:"active"}
                ]);
            }else if(sourceNode.type == 'JqpCondition'){
                //条件流转
                content = this.getProperties([
                    {label:"当前状态",placeholder:"当此条件流转时,修改当前表的状态,如果为空,则不更新",name:"status"},
                    {label:"判断顺序",placeholder:"判断流转的优先级,数字越小,优先级越高",name:"checkSeq"},
                    {label:"判断类型",name:"checkType",options:[{
                        value:"表达式",
                        label:"表达式"
                    },{
                        value:"magicApi",
                        label:"magicApi"
                    }]},
                    {label:"判断配置",placeholder:"如果是表达式,请填写表达式,如果是magicApi,请填写post请求的magicApi地址,返回布尔值",name:"checkConfig",type:"textarea"}
                ]);
            }
        }else if(nodeType == 'JqpUserTask'){
            content = this.getProperties([
                {label:"当前状态",placeholder:"用于判断哪些状态能进行下一步操作",name:"status",multiple:"multiple"},
                {label:"审批页面",placeholder:"如果页面编号为空,则取公共页面,页面编号",name:"page"},
                {label:"审批方式",name:"checkType",options:[{
                    value:"任意成员审核通过",
                    label:"任意成员审核通过"
                },{
                    value:"全部成员审核通过",
                    label:"全部成员审核通过"
                }]},
                {label:"审核人类型",name:"userType",options:[{
                    value:"指定成员",
                    label:"指定成员"
                },{
                    value:"主管",
                    label:"主管"
                },{
                    value:"角色",
                    label:"角色"
                },{
                    value:"通过接口获取",
                    label:"通过接口获取"
                },{
                    value:"提交人审核",
                    label:"提交人审核"
                }]},
                {label:"指定成员",placeholder:"用户编码,多个用逗号分隔",name:"users",condition:()=>{
                    return this.state.curNode.data.properties.userType == "指定成员";
                }},
                {label:"第几级主管",placeholder:"当前用户所在部门层级为1,向上依次递增",name:"depLevel",condition:()=>{
                    return this.state.curNode.data.properties.userType == "主管";
                }},
                {label:"角色",placeholder:"角色编码,多个用逗号分隔",name:"roleCodes",condition:()=>{
                    return this.state.curNode.data.properties.userType == "角色";
                }},
                {label:"获取成员接口",placeholder:"magicApi地址,post请求,返回成员id数组",name:"userApi",condition:()=>{
                    return this.state.curNode.data.properties.userType == "通过接口获取";
                }}

                //{label:"激活",name:"active"},
            ]);
        }
        if(!content) return null;
        return <div className={"Properties"}>
            <div className={"Properties-Title"}>属性面板-{this.state.curNode.data.text && this.state.curNode.data.text.value}</div>
            <Form  labelCol={{
                span: 6,
            }} wrapperCol={{
                span: 18,
            }} style={{

            }}  layout={"horizontal"}>
                {content}
            </Form>
        </div>;
    }
    render(){
        const showProperties = window.showProperties === false ? false : true;
        if(!showProperties){
            return null;
        }
        return this.state.curNode ?
            this.getEditors() : null
    }
}
